function getBluejlegalTranslation(key, lang) {
    if (bluejlegalTranslations[lang] && bluejlegalTranslations[lang][key]) {
        return bluejlegalTranslations[lang][key];
    }
    if (bluejlegalTranslations.en && bluejlegalTranslations.en[key]) {
        return bluejlegalTranslations.en[key];
    }
    return null;
}

function applyBluejlegalTranslations(lang) {
    console.log('Applying blue-j-legal translations for:', lang);
    let count = 0;
    document.querySelectorAll('[data-i18n]').forEach(element => {
        const key = element.getAttribute('data-i18n');
        if (key && key.startsWith('review.blue-j-legal.')) {
            const translation = getBluejlegalTranslation(key, lang);
            if (translation) {
                element.textContent = translation;
                count++;
            }
        }
    });
    console.log(`Applied ${count} blue-j-legal translations`);
}

window.addEventListener('languageChanged', (e) => {
    const lang = e.detail.language;
    setTimeout(() => applyBluejlegalTranslations(lang), 200);
});

if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', () => {
        const currentLang = window.i18n ? window.i18n.getCurrentLanguage() : 'en';
        applyBluejlegalTranslations(currentLang);
    });
} else {
    const currentLang = window.i18n ? window.i18n.getCurrentLanguage() : 'en';
    applyBluejlegalTranslations(currentLang);
}

console.log('blue-j-legal i18n loaded');
